package jp.tapmarker;
import java.util.*;
/** Exit labels, countdown rejection, polarity and per-display fallback sequence. */
public final class AdExitPolicyTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static PhaseEngine graph()throws Exception{PhaseEngine e=new PhaseEngine();FarmPreset.install(e,VirtualPresetProfileTest.canonical("tests/farm-replay.bin"));e.strictRuntime=true;AdCloseAutomaton.install(e,FarmPreset.APP);e.enter(FarmPreset.P+"ad",0);return e;}
 static Map<String,float[]> x(){Map<String,float[]> m=new HashMap<>();m.put(AdCloseAutomaton.RIGHT,new float[]{1});m.put(AdCloseAutomaton.RIGHT+AdCloseAutomaton.POINT,new float[]{390,20});return m;}
 public static void main(String[] args)throws Exception{
  for(String label:new String[]{"閉じる","広告を閉じる","スキップ","Skip ad","Close","×","X"})check(AdExitPolicy.corner(label,new float[]{.86f,.02f,.98f,.06f}).equals(AdCloseAutomaton.RIGHT),"explicit exit label: "+label);
  for(String label:new String[]{"プレイ","Play now","インストール","Install","ダウンロード","あと5秒","5","報酬を受け取る","次へ","OK","広告を見る"})check(AdExitPolicy.corner(label,new float[]{.86f,.02f,.98f,.06f}).isEmpty(),"play, purchase and countdowns never authorize an ad input: "+label);
  check(AdExitPolicy.corner("close",new float[]{.2f,.5f,.7f,.7f}).isEmpty(),"center play area is excluded");
  check(AdExitPolicy.corner("閉じる",new float[]{.2f,.65f,.8f,.7f}).isEmpty(),"farm reward button is separate from ad exits");
  check(AdExitPolicy.corner("広告を閉じる",new float[]{.2f,.50f,.8f,.58f}).equals(AdCloseAutomaton.RIGHT),"explicit ad dismissal after Back can be centred");
  check(AdExitPolicy.corner("プレイを続ける",new float[]{.2f,.50f,.8f,.58f}).isEmpty(),"ad continuation confirmation is never chosen");
  int width=400,height=900;float[] roi={.78f,0,1,.14f};
  for(boolean light:new boolean[]{false,true}){RegionSampler.Pixels pixels=(x,y)->x>=372&&x<=388&&y>=12&&y<=28&&(Math.abs((x-372)-(y-12))<=1||Math.abs((x-372)+(y-12)-16)<=1)?(light?0xff333333:0xffffffff):(light?0xffeeeeee:0xff111111);float[] p=AdCloseDetector.find(width,height,roi,pixels);check(p!=null&&Math.abs(p[0]-380.5)<1&&Math.abs(p[1]-20.5)<1,"actual X center at either polarity");}
  RegionSampler.Pixels plus=(x,y)->x>=372&&x<=388&&Math.abs(y-20)<=1||y>=12&&y<=28&&Math.abs(x-380)<=1?0xff111111:0xffffffff;check(AdCloseDetector.find(width,height,roi,plus)==null,"dark plus is not a close");
  Map<String,float[]> control=new HashMap<>();check(AdCloseAutomaton.putControl(control,AdCloseAutomaton.RIGHT,380,20,width,height),"named close supplies dimension-tagged point");check(AdCloseAutomaton.controlPoint(AdCloseAutomaton.RIGHT,control,width,height)!=null&&AdCloseAutomaton.controlPoint(AdCloseAutomaton.RIGHT,control,width+1,height)==null,"named point becomes invalid after resize");control.put(AdCloseAutomaton.RIGHT,new float[]{0});check(AdCloseAutomaton.controlPoint(AdCloseAutomaton.RIGHT,control,width,height)==null,"missing close invalidates named input");
  PhaseEngine e=graph();PhaseEngine.Watch timer=e.rule(FarmPreset.P+"ad-timeout");check(timer.timeoutMs==30000,"ordinary ad receives an initial 30 second end wait");e.observe(Collections.emptyMap(),29999);check(e.poll()==null,"no early escape during initial wait");e.observe(x(),30000);check(e.poll()==null,"first visible X beats expired fallback and waits for confirmation");e.observe(x(),30350);PhaseEngine.Watch close=e.poll();check(close!=null&&AdCloseAutomaton.handles(close.regionId),"fresh confirmed X wins over back/relaunch");
  AdExitPolicy a=new AdExitPolicy(),b=new AdExitPolicy();e=graph();timer=e.rule(FarmPreset.P+"ad-timeout");a.observe(e,Collections.emptyMap());check(a.choose(e,timer,Collections.emptyMap(),30000)==PhaseEngine.BACK,"first fallback is targeted Back");a.sent(30000);check(a.choose(e,timer,Collections.emptyMap(),31000)==PhaseEngine.WAIT,"rapid repeated Back is held");e.enter(FarmPreset.P+"verify",32000);timer=e.rule(FarmPreset.P+"verify-timeout");check(a.choose(e,timer,Collections.emptyMap(),38000)==PhaseEngine.BACK,"second missing exit can dismiss a confirmation/end card");a.sent(38000);check(a.choose(e,timer,Collections.emptyMap(),44000)==PhaseEngine.RETURN_APP,"third attempt falls back to existing app recovery");check(b.choose(e,timer,Collections.emptyMap(),44000)==PhaseEngine.RETURN_APP,"another runner does not inherit ad state");
  PhaseEngine.Watch home=e.rule(FarmPreset.P+"verify-home");Map<String,float[]> game=new HashMap<>();game.put(home.regionId,home.reference.clone());a.observe(e,game);check(a.choose(e,timer,Collections.emptyMap(),45000)==PhaseEngine.RETURN_APP,"verified game ends the ad episode");e.enter(FarmPreset.P+"ad",46000);timer=e.rule(FarmPreset.P+"ad-timeout");check(a.choose(e,timer,Collections.emptyMap(),76000)==PhaseEngine.BACK,"next ad has a fresh Back budget");a.rejected();check(a.choose(e,timer,Collections.emptyMap(),77000)==PhaseEngine.RETURN_APP,"rejected targeted Back yields to recovery");
  PhaseEngine coin=new PhaseEngine();CoinPreset.install(coin,VirtualPresetProfileTest.canonical("tests/video6687-references.bin"));AdCloseAutomaton.install(coin,CoinPreset.APP);check(coin.rule(CoinPreset.P+"reward-ad-timeout").timeoutMs==30000,"coin opt-out removes the old 120-second reward-viewing wait");check(BancAutonomy.safeKind("プレイ","広告 インストール").isEmpty(),"BANC never creates a playable-ad Play operation");
  System.out.println("AdExitPolicyTest: "+checks+" checks passed; named exits, contrast, input priority and per-runner recovery; unseen playable ad device interaction untested");
 }
}
